        </p>
        <div id="faq-root" class="faq-list" aria-label="Cat frequently asked questions"></div>
      </section>
    </main>

    <script>
      const faqData = [
        {
          question: "Why do cats purr?",
          answer: [
            "Cats purr for several reasons, including contentment, comfort, and sometimes self-soothing when they are stressed or unwell.",
            "If your cat is purring while kneading a blanket or curling up beside you, they are probably feeling safe and relaxed."
          ]
        },
        {
          question: "How much do cats sleep?",
          answer: [
            "Most adult cats sleep between 12 and 16 hours a day, and kittens or senior cats can sleep even more.",
            "That long rest cycle helps them conserve energy for short bursts of hunting, playing, and investigating the world."
          ]
        },
        {
          question: "Do indoor cats need enrichment?",
          answer: [
            "Yes. Indoor cats still need mental and physical stimulation to stay healthy and happy.",
            "Puzzle feeders, climbing shelves, window perches, scratching posts, and interactive play can make a big difference."
          ]
        },
        {
          question: "Why do cats knead with their paws?",
          answer: [
            "Kneading is a comforting behavior that often starts in kittenhood when nursing.",
            "Adult cats may knead when they are relaxed, scent-marking, or preparing a cozy spot to rest."
          ]
        }
      ];

      function createFAQItem(item, index) {
        const wrapper = document.createElement("div");
        wrapper.className = "example";
        wrapper.dataset.open = "false";

        const button = document.createElement("button");
        button.type = "button";
        button.className = "question-button";
        button.id = `faq-button-${index}`;
        button.setAttribute("aria-expanded", "false");
        button.setAttribute("aria-controls", `faq-panel-${index}`);

        const question = document.createElement("span");
        question.className = "question";
        question.textContent = item.question;

        const chevron = document.createElement("span");
        chevron.className = "chevron";
        chevron.setAttribute("aria-hidden", "true");

        button.append(question, chevron);

        const details = document.createElement("div");
        details.className = "details";
        details.id = `faq-panel-${index}`;
        details.setAttribute("role", "region");
        details.setAttribute("aria-labelledby", button.id);
        details.hidden = true;

        const detailsInner = document.createElement("div");
        detailsInner.className = "details-inner";

        const answer = document.createElement("div");
        answer.className = "answer";
        item.answer.forEach((paragraph) => {
          const p = document.createElement("p");
          p.textContent = paragraph;
          answer.appendChild(p);
        });

        detailsInner.appendChild(answer);
        details.appendChild(detailsInner);

        button.addEventListener("click", () => {
          const isOpen = button.getAttribute("aria-expanded") === "true";
          button.setAttribute("aria-expanded", String(!isOpen));
          wrapper.dataset.open = String(!isOpen);
          details.hidden = isOpen;
        });

        wrapper.append(button, details);
        return wrapper;
      }

